const payload = $input.first().json;
const userId = payload.userId;
const month = payload.data?.month || new Date().toISOString().slice(0, 7);

return [{
  json: {
    userId,
    month,
    logId: payload.logId
  }
}];

const budgets = $input.first().json;
const prev = $('Extract Params').first().json;

if (!Array.isArray(budgets) || budgets.length < 2) {
  return [];
}

// Find overspending and underspending
const analyzed = budgets.map(b => {
  const limit = b.limitAmount || 0;
  const spent = b.spentAmount || 0;
  const util = limit > 0 ? (spent / limit) * 100 : 0;
  const remaining = Math.max(0, limit - spent);
  return { category: b.category, limit, spent, util, remaining };
});

const over = analyzed.filter(b => b.util >= 85).sort((a, b) => b.util - a.util);
const under = analyzed.filter(b => b.util <= 50 && b.remaining >= 500).sort((a, b) => b.remaining - a.remaining);

if (over.length > 0 && under.length > 0) {
  const target = over[0];
  const source = under[0];
  const reallocate = Math.min(Math.round(source.remaining * 0.5), Math.max(500, Math.round(target.spent - target.limit * 0.8)));

  return [{
    json: {
      userId: prev.userId,
      month: prev.month,
      sourceCategory: source.category,
      targetCategory: target.category,
      reallocateAmount: reallocate,
      sourceCurrentBudget: source.limit,
      targetCurrentBudget: target.limit,
      reason: `${target.category} spending is at ${Math.round(target.util)}% of limit. You have ₹${source.remaining.toLocaleString()} remaining in ${source.category}. Reallocating ₹${reallocate.toLocaleString()} prevents budget overrun.`,
      aiConfidence: 0.94,
      logId: prev.logId
    }
  }];
}

return [];
